package ar.edu.utn.frc.tup.app.entities;

import jakarta.persistence.*;
import jakarta.validation.constraints.NotNull;
import lombok.*;
import org.hibernate.annotations.ColumnDefault;

import java.time.LocalDate;

@Getter
@Setter
@Entity
@Builder
@Table(name = "profesionales")
@AllArgsConstructor
@NoArgsConstructor
public class Profesionale {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "idprofesional", nullable = false)
    private Integer id;

    @NotNull
    @Column(name = "fechadesde", nullable = false)
    private LocalDate fechadesde;

    @Column(name = "fechahasta")
    private LocalDate fechahasta;

    @NotNull
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "idusuario", nullable = false)
    private Usuario idusuario;

    @NotNull
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "idoficio", nullable = false)
    private Oficio idoficio;

    @Column(name = "precio_min")
    private Integer precioMin;

    @Column(name = "precio_max")
    private Integer precioMax;
}

package ar.edu.utn.frc.tup.app.entities;

import jakarta.persistence.*;
import jakarta.validation.constraints.NotNull;
import lombok.*;
import org.hibernate.annotations.ColumnDefault;

import java.time.LocalDate;
import java.util.List;

@Getter
@Setter
@Entity
@Builder
@Table(name = "profesionales")
@AllArgsConstructor
@NoArgsConstructor
public class Profesionale {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "idprofesional", nullable = false)
    private Integer id;

    @NotNull
    @Column(name = "fechadesde", nullable = false)
    private LocalDate fechadesde;

    @Column(name = "fechahasta")
    private LocalDate fechahasta;

    @NotNull
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "idusuario", nullable = false)
    private Usuario idusuario;

    @NotNull
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "idoficio", nullable = false)
    private Oficio idoficio;

    @Column(name = "precio_min")
    private Integer precioMin;

    @Column(name = "precio_max")
    private Integer precioMax;

    @OneToMany(mappedBy = "idprofesional", fetch = FetchType.LAZY)
    private List<Especialidad> especialidades;
}

package ar.edu.utn.frc.tup.app.repositories;

import ar.edu.utn.frc.tup.app.entities.Profesionale;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

@Repository
public interface ProfesionalRepository extends JpaRepository<Profesionale, Integer> {
    @Query("SELECT p FROM Profesionale p " +
            "JOIN p.idoficio o " +
            "JOIN p.idusuario u " +
            "JOIN u.iddireccion d " +
            "JOIN d.idbarrio b " +
            "JOIN b.idciudad c " +
            "WHERE (:oficio IS NULL OR LOWER(o.oficio) LIKE LOWER(CONCAT('%', :oficio, '%'))) " +
            "AND (:zona IS NULL OR LOWER(b.barrio) LIKE LOWER(CONCAT('%', :zona, '%')) " +
            "    OR LOWER(c.ciudad) LIKE LOWER(CONCAT('%', :zona, '%')))")
    List<Profesionale> findByOficioAndZona(@Param("oficio") String oficio, @Param("zona") String zona);

    @Query("SELECT p FROM Profesionale p " +
            "JOIN p.idoficio o " +
            "WHERE LOWER(o.oficio) LIKE LOWER(CONCAT('%', :oficio, '%'))")
    List<Profesionale> findByOficio(@Param("oficio") String oficio);

    @Query("SELECT p FROM Profesionale p " +
            "JOIN p.idusuario u " +
            "JOIN u.iddireccion d " +
            "JOIN d.idbarrio b " +
            "JOIN b.idciudad c " +
            "WHERE LOWER(b.barrio) LIKE LOWER(CONCAT('%', :zona, '%')) " +
            "   OR LOWER(c.ciudad) LIKE LOWER(CONCAT('%', :zona, '%'))")
    List<Profesionale> findByZona(@Param("zona") String zona);

    @Query("SELECT p FROM Profesionale p " +
            "JOIN p.idusuario u " +
            "JOIN u.iddireccion d " +
            "JOIN d.idbarrio b " +
            "JOIN b.idciudad c " +
            "WHERE p.fechahasta IS NULL OR p.fechahasta >= CURRENT_DATE")
    List<Profesionale> findProfesionalesActivos();

    Optional<Profesionale> findByIdusuario_Id(Integer idUsuario);
}

package ar.edu.utn.frc.tup.app.repositories;

import ar.edu.utn.frc.tup.app.entities.Profesionale;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

@Repository
public interface ProfesionalRepository extends JpaRepository<Profesionale, Integer> {
    @Query("SELECT DISTINCT p FROM Profesionale p " +
            "LEFT JOIN FETCH p.especialidades " +
            "JOIN p.idoficio o " +
            "JOIN p.idusuario u " +
            "JOIN u.iddireccion d " +
            "JOIN d.idbarrio b " +
            "JOIN b.idciudad c " +
            "WHERE (:oficio IS NULL OR LOWER(o.oficio) LIKE LOWER(CONCAT('%', :oficio, '%'))) " +
            "AND (:zona IS NULL OR LOWER(b.barrio) LIKE LOWER(CONCAT('%', :zona, '%')) " +
            "    OR LOWER(c.ciudad) LIKE LOWER(CONCAT('%', :zona, '%')))")
    List<Profesionale> findByOficioAndZona(@Param("oficio") String oficio, @Param("zona") String zona);

    @Query("SELECT DISTINCT p FROM Profesionale p " +
            "LEFT JOIN FETCH p.especialidades " +
            "JOIN p.idoficio o " +
            "WHERE LOWER(o.oficio) LIKE LOWER(CONCAT('%', :oficio, '%'))")
    List<Profesionale> findByOficio(@Param("oficio") String oficio);

    @Query("SELECT DISTINCT p FROM Profesionale p " +
            "LEFT JOIN FETCH p.especialidades " +
            "JOIN p.idusuario u " +
            "JOIN u.iddireccion d " +
            "JOIN d.idbarrio b " +
            "JOIN b.idciudad c " +
            "WHERE LOWER(b.barrio) LIKE LOWER(CONCAT('%', :zona, '%')) " +
            "   OR LOWER(c.ciudad) LIKE LOWER(CONCAT('%', :zona, '%'))")
    List<Profesionale> findByZona(@Param("zona") String zona);

    @Query("SELECT DISTINCT p FROM Profesionale p " +
            "LEFT JOIN FETCH p.especialidades " +
            "JOIN p.idusuario u " +
            "JOIN u.iddireccion d " +
            "JOIN d.idbarrio b " +
            "JOIN b.idciudad c " +
            "WHERE p.fechahasta IS NULL OR p.fechahasta >= CURRENT_DATE")
    List<Profesionale> findProfesionalesActivos();

    @Query("SELECT p FROM Profesionale p " +
            "LEFT JOIN FETCH p.especialidades " +
            "WHERE p.idusuario.id = :idUsuario")
    Optional<Profesionale> findByIdusuario_Id(@Param("idUsuario") Integer idUsuario);
}
